#include <stdio.h>

int main(void) {
    int a, b;
    scanf("%d %d", &a, &b);
    int average = a + b / 2;
    printf("%d\n", average);
    return 0;
}

exercise.referenceSolution:
#include <stdio.h>

int main(void) {
    int a, b;
    scanf("%d %d", &a, &b);
    int average = (a + b) / 2;
    printf("%d\n", average);
    return 0;
}

